<?php declare(strict_types=1);$indData=$inventoryIndividualDraft;$known=0;$unknown=0;$total=0; ?>
<section class="card iv-individual-review" id="inventory-individual-review" data-individual-review><h2><?= e($indText('{count} Einzelstücke vor dem Anlegen prüfen',['count'=>(string)count($indData['units'])])) ?></h2><p><?= e($indText('Jedes Stück erhält einen eigenen Eintrag und genau einen tatsächlichen Anfangsbestand am ausgewählten Lagerort. Vorhandene Belege werden nur verknüpft; es entstehen keine neuen Rechnungen oder Zahlungen.')) ?></p>
<ol><?php foreach($indData['preview']as$preview):$u=$preview['data']; ?><li><h3><?= e($u['name']) ?></h3><dl><dt><?= e($indText('Inventarnummer')) ?></dt><dd><?= e($u['code']!==''?$u['code']:$indText('Wird beim Anlegen automatisch vergeben')) ?></dd><dt><?= e($indText('Seriennummer')) ?></dt><dd><?= e($u['serial_number']!==''?$u['serial_number']:$indText('Noch nicht bekannt')) ?></dd><dt><?= e($indText('Tatsächlicher Lagerort')) ?></dt><dd><?= e($preview['location']['name']) ?></dd><dt><?= e($indText('Anschaffungsdatum')) ?></dt><dd><?= e($u['acquired_on']!==''?$u['acquired_on']:$indText('Noch nicht bekannt')) ?></dd><?php if($canFinance): ?><dt><?= e($indText('Preis dieses Einzelstücks')) ?></dt><dd><?php if($preview['unit_value_cents']===null):$unknown++;echo e($indText('Preis unbekannt'));else:$known++;$total+=$preview['unit_value_cents'];echo euro($preview['unit_value_cents']);endif ?></dd><dt><?= e($indText('Verknüpfter Beleg')) ?></dt><dd><?= e($preview['source']?((string)($preview['source']['designation']??'')!==''?$preview['source']['designation']:$preview['source']['description']):$indText('Keine Verknüpfung')) ?></dd><dt><?= e($indText('Wertnachweis')) ?></dt><dd><?= e($u['value_note']) ?></dd><?php endif ?></dl></li><?php endforeach ?></ol>
<?php if($canFinance): ?><p><?= e($indText('Bekannte Einzelpreise zusammen:')) ?> <strong><?= euro($total) ?></strong> · <?= e($indText('{count} Preise noch unbekannt',['count'=>(string)$unknown])) ?></p><?php endif ?>
<form method="post" action="<?= e($individualAction) ?>#inventory-individual-review" data-individual-confirm>
<?= csrf().hidden('action','inventory-individuals').hidden('target','').hidden('version','0').hidden('request_key',$inventoryIndividualState['key']).hidden('source_form','individual').hidden('unit_count',$indData['unit_count']).hidden('review_token',$indData['review_token']) ?>
<?php if($canFinance)echo hidden('price_suggestion',$indData['price_suggestion']);foreach($indData['common']as$field=>$value)echo hidden('common['.$field.']',$value);foreach($indData['units']as$ix=>$row)foreach($row as$field=>$value)echo hidden('units['.$ix.']['.$field.']',$value); ?>
<?= hidden('individual_form_complete','1') ?>
<div class="iv-individual-actions"><button class="btn btn-outline theme-secondary" name="individual_step" value="edit" formnovalidate><?= e($indText('Zurück und Angaben ändern')) ?></button><button class="btn btn-solid theme-primary" name="confirmed" value="1"><?= e($indText('Diese {count} Einzelstücke jetzt anlegen',['count'=>(string)count($indData['units'])])) ?></button></div>
</form></section>
